<?php
function lop_targets(array $plan,array $cfg): void {
    global $id;$code=(string)($_GET['targets']??'');$group=$plan['groups'][$code]??null;if(!$group)return;
    $q=mb_strtolower(trim((string)($_GET['target_q']??'')));$rows=[];foreach($group['identities'] as $identity){$o=$plan['owners'][$identity]??null;if($o&&($q===''||str_contains(mb_strtolower($o['name'].' '.$identity),$q)))$rows[]=$o;}
    $page=max(1,min(max(1,(int)ceil(count($rows)/25)),(int)($_GET['target_page']??1)));
    $accountCount=0;$balanceTotal=0;$unknown=0;foreach($group['identities'] as $identity){$b=$plan['owners'][$identity]['bank_summary']??[];$accountCount+=(int)($b['accounts']??0);if(isset($b['source_balance']))$balanceTotal+=lf_cents($b['source_balance']);else $unknown++;}
    echo '<section class="dbt-card lop-targets" id="group-targets"><h2>Sasaran kelompok '.loe($group['label']??$code).'</h2><p>'.count($group['identities']).' identitas dalam kelompok. '.$accountCount.' rekening utama ? Saldo sumber tercatat '.loe(legacy_ui_money(lf_money($balanceTotal))).' ? '.$unknown.' identitas tanpa saldo sumber pasti. Tabungan tambahan ditampilkan terpisah dari saldo utama.</p><form method="get" class="lf-search"><input type="hidden" name="id" value="'.loe($id).'"><input type="hidden" name="section" value="groups"><input type="hidden" name="targets" value="'.loe($code).'"><label>Cari nama / identitas<input name="target_q" value="'.loe($q).'"></label><button class="dbt-button">Cari</button></form><div class="dbt-table-scroll"><table class="dbt-table lop-target-table"><thead><tr><th>Identitas</th><th>Tarif sumber</th><th>Rekening</th><th>Saldo utama</th><th>Tindakan</th></tr></thead><tbody>';
    foreach(array_slice($rows,($page-1)*25,25) as $o){$b=$o['bank_summary']??[];$fix=$cfg['op_savings'][$o['identity']]??[];
        echo '<tr><td data-label="Identitas"><strong>'.loe($o['name']).'</strong><small>'.loe($o['identity']).' · '.loe($o['source_class']).'</small><small>Tahun masuk '.loe($o['entry_year']??'Tidak tercatat').'</small></td><td data-label="Tarif sumber">SPP '.loe(legacy_ui_money($o['spp'])).'<small>Komite '.loe(legacy_ui_money($o['komite'])).'</small></td><td data-label="Rekening">'.(int)($b['accounts']??0).' utama<small>'.(int)($b['additional_accounts']??0).' catatan rekening tambahan</small><small>'.loe($b['status']??'Tidak tercatat').'</small></td><td data-label="Saldo utama">Sumber '.loe(legacy_ui_money($b['source_balance']??null)).'<small>Jurnal '.loe(legacy_ui_money($b['journal_balance']??null)).'</small><small>Selisih '.loe(legacy_ui_money(isset($b['source_balance'],$b['journal_balance'])?lf_money(lf_cents($b['source_balance'])-lf_cents($b['journal_balance'],true)):null)).'</small><small>FIX '.loe(legacy_ui_money(!empty($fix['confirmed'])?$fix['amount']:null)).'</small></td><td data-label="Tindakan"><a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'savings','person'=>$o['identity']])).'">Tinjau Tabungan</a></td></tr>';
    }
    echo '</tbody></table></div><nav class="legacy-actions"><span>'.count($rows).' hasil · Halaman '.$page.' / '.max(1,(int)ceil(count($rows)/25)).'</span>';foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $delta=>$label){$p=$page+$delta;if($p>0&&($p-1)*25<count($rows))echo '<a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'groups','targets'=>$code,'target_q'=>$q,'target_page'=>$p])).'#group-targets">'.$label.'</a>';}echo '</nav></section>';
}
function lop_groups_form(array $plan,array $cfg,array $classes): void {
    global $id;
    echo '<section class="dbt-card"><h2>Sahkan per kelompok</h2><p>Periksa jenis kelompok dan identitas sebelum menyimpan draf.</p><div class="lop-group-list">';
    foreach($plan['groups'] as $code=>$g){$saved=$cfg['op_groups'][$code]??[];$year=$saved['graduation_year']??$g['graduation_year']??'';
        echo '<details class="lf-debt"><summary><span>'.loe($g['label']??$code).'</span><span class="lop-count">'.count($g['identities']).' identitas</span></summary><div class="lop-group-body"><p>Ejaan sumber: '.loe(implode(', ',$g['aliases'])).'</p><a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'groups','targets'=>$code])).'#group-targets">Lihat seluruh sasaran &amp; tabungan</a><input type="hidden" name="op_groups['.loe($code).'][fingerprint]" value="'.loe($g['fingerprint']).'"><div class="lful-grid"><label>Jenis kelompok<select name="op_groups['.loe($code).'][kind]">';
        foreach(['academic'=>'Kelas akademik','psb'=>'PSB','out'=>'Siswa keluar','alumni'=>'Alumni','account'=>'Rekening non-siswa','legacy'=>'Belum diklasifikasikan'] as $kind=>$text)echo '<option value="'.$kind.'" '.(($saved['kind']??$g['kind'])===$kind?'selected':'').'>'.$text.'</option>';
        echo '</select></label><label>Tahun lulus (khusus Alumni)<input name="op_groups['.loe($code).'][graduation_year]" inputmode="numeric" pattern="20[0-9]{2}" placeholder="Contoh: 2025" value="'.loe($year).'"></label></div>';
        if($year)echo '<p class="dbt-info">Saran: Alumni'.loe($year).' berdasarkan kode kelompok '.loe($code).'. Tahun masuk tiap identitas tetap ditampilkan terpisah.</p>';
        echo '<label>Rombel tujuan (khusus kelas akademik)<select name="op_groups['.loe($code).'][target_class_id]"><option value="">Ikuti kode sumber sesuai jenjang</option>';foreach($classes as $cl)if((int)$cl['tingkat']>0)echo '<option value="'.(int)$cl['id'].'" '.((int)($saved['target_class_id']??0)===(int)$cl['id']?'selected':'').'>'.loe(class_label($cl)).'</option>';
        echo '</select></label><label>Bukti klasifikasi<textarea name="op_groups['.loe($code).'][evidence]" minlength="10" maxlength="1000">'.loe($saved['evidence']??'').'</textarea></label><div class="lop-consents">';
        foreach(['confirmed'=>'Saya mengesahkan seluruh '.count($g['identities']).' identitas dan jenis kelompok ini.','obligations_attested'=>'Kewajiban kelompok sudah diperiksa. Tunggakan dicatat terpisah bila ada.','savings_attested'=>'Saldo dan jurnal yang cocok sudah diperiksa.'] as $key=>$text)echo '<label class="lop-check"><input type="checkbox" name="op_groups['.loe($code).']['.$key.']" value="1" '.(!empty($saved[$key])?'checked':'').'><span>'.$text.'</span></label>';
        echo '</div></div></details>';
    }echo '</div></section>';
    $testing=array_filter($plan['owners'],fn($o)=>!empty($o['testing_candidate']));if($testing){echo '<section class="dbt-card"><h2>Rekening Uji Legacy</h2><p>Identitas berikut diusulkan sebagai rekening uji dengan ID internal, tanpa NIS baru atau SPP otomatis.</p><div class="lop-consents">';foreach($testing as $o)echo '<label class="lop-check"><input type="hidden" name="testing['.loe($o['identity']).']" value="0"><input type="checkbox" name="testing['.loe($o['identity']).']" value="1" '.(!empty($cfg['students'][$o['identity']]['testing_confirmed'])?'checked':'').'><span>'.loe($o['name']).' · '.loe($o['identity']).' · '.loe($o['source_class']).'</span></label>';echo '</div></section>';}
}
